def arrayNesting(A):
    visited = [False] * len(A)
    max_length = 0

    for i in range(len(A)):
        if not visited[i]:
            current_length = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = A[j]
                current_length += 1
            max_length = max(max_length, current_length)

    return max_length
